(()=>{
'use strict';
const $=id=>document.getElementById(id), STORAGE='lunea-location-v1';
const builtins=[
{id:'donostia',name:'Donostia / San Sebastián',admin1:'Gipuzkoa',country:'España',latitude:43.3183,longitude:-1.9812,timezone:'Europe/Madrid',aliases:'donosti san sebastian'},
{id:'oslo',name:'Oslo',admin1:'Oslo',country:'Noruega',latitude:59.9139,longitude:10.7522,timezone:'Europe/Oslo'},
{id:'bergen',name:'Bergen',admin1:'Vestland',country:'Noruega',latitude:60.3913,longitude:5.3221,timezone:'Europe/Oslo'},
{id:'buenos-aires',name:'Buenos Aires',admin1:'Ciudad Autónoma de Buenos Aires',country:'Argentina',latitude:-34.6037,longitude:-58.3816,timezone:'America/Argentina/Buenos_Aires'},
{id:'madrid',name:'Madrid',admin1:'Madrid',country:'España',latitude:40.4168,longitude:-3.7038,timezone:'Europe/Madrid'},
{id:'sydney',name:'Sídney',admin1:'Nueva Gales del Sur',country:'Australia',latitude:-33.8688,longitude:151.2093,timezone:'Australia/Sydney',aliases:'sydney'},
{id:'auckland',name:'Auckland',admin1:'Auckland',country:'Nueva Zelanda',latitude:-36.8485,longitude:174.7633,timezone:'Pacific/Auckland'},
{id:'new-york',name:'Nueva York',admin1:'Nueva York',country:'Estados Unidos',latitude:40.7128,longitude:-74.006,timezone:'America/New_York',aliases:'new york'}];
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function valid(c){if(!c||typeof c.name!=='string'||!Number.isFinite(c.latitude)||Math.abs(c.latitude)>90||!Number.isFinite(c.longitude)||Math.abs(c.longitude)>180||typeof c.timezone!=='string')return false;try{new Intl.DateTimeFormat('es',{timeZone:c.timezone});return true}catch{return false}}
let saved={};try{saved=JSON.parse(localStorage.getItem(STORAGE))||{}}catch{}
const state=window.LuneaLocation={active:valid(saved.active)?saved.active:builtins[0],favorites:Array.isArray(saved.favorites)?saved.favorites.filter(valid):[],known:Array.isArray(saved.known)?saved.known.filter(valid).slice(-100):[]};
let results=[],requestId=0,controller;
const same=(a,b)=>a.timezone===b.timezone&&Math.abs(a.latitude-b.latitude)<.03&&Math.abs(a.longitude-b.longitude)<.03;
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));return true}catch{$('city-status').textContent='El navegador no permite guardar los cambios. Se conservarán mientras la app esté abierta.';return false}}
function select(c){state.active=c;state.known=[...state.known.filter(x=>!same(x,c)),c].slice(-100);persist();draw();window.dispatchEvent(new Event('lunea-location-change'))}
function favorite(c){const i=state.favorites.findIndex(x=>same(x,c));if(i<0)state.favorites.push(c);else state.favorites.splice(i,1);persist();draw()}
function rows(target,cities,isFavorites){target.replaceChildren();for(const c of cities){const row=document.createElement('div');row.className='city-row';const choose=document.createElement('button');choose.type='button';choose.className='city-choice';choose.setAttribute('aria-pressed',String(same(c,state.active)));const name=document.createElement('span');name.textContent=c.name+(same(c,state.active)?' · Activa':'');const region=document.createElement('small');region.textContent=[c.admin1,c.country].filter(Boolean).join(', ');choose.append(name,region);choose.onclick=()=>select(c);const star=document.createElement('button');star.type='button';star.className='star';const isSaved=state.favorites.some(x=>same(x,c));star.textContent=isSaved?'★':'☆';star.setAttribute('aria-label',(isSaved?'Quitar de favoritas: ':'Guardar en favoritas: ')+c.name);star.setAttribute('aria-pressed',String(isSaved));star.onclick=()=>favorite(c);row.append(choose,star);target.append(row)}if(isFavorites&&!cities.length){const p=document.createElement('p');p.textContent='Pulsa la estrella de una ciudad para guardarla.';target.append(p)}}
function draw(){$('active-city').textContent=state.active.name;rows($('city-results'),results,false);rows($('city-favorites'),state.favorites,true)}
function unique(cities){return cities.filter((c,i)=>cities.findIndex(x=>same(x,c))===i)}
$('city-search').onsubmit=async e=>{e.preventDefault();const q=$('city-query').value.trim(),token=++requestId;if(controller)controller.abort();if(q.length<2){results=[];draw();$('city-status').textContent='Escribe al menos dos letras.';return}results=unique([...state.known,...state.favorites,...builtins].filter(c=>norm([c.name,c.admin1,c.country,c.aliases||''].join(' ')).includes(norm(q))));draw();$('city-status').textContent='Buscando ciudades…';controller=new AbortController();const currentController=controller;const timer=setTimeout(()=>currentController.abort(),8000);try{const response=await fetch('https://geocoding-api.open-meteo.com/v1/search?'+new URLSearchParams({name:q,count:'12',language:'es',format:'json'}),{signal:controller.signal});if(!response.ok)throw new Error('search');const data=await response.json();if(token!==requestId)return;const remote=(data.results||[]).filter(c=>!c.feature_code||c.feature_code.startsWith('PPL')).filter(valid);results=unique([...results,...remote]);draw();$('city-status').textContent=results.length?'Elige una ciudad o guárdala con la estrella.':'No hay resultados. Prueba el nombre de la ciudad seguido de su país.'}catch{if(token!==requestId)return;$('city-status').textContent=results.length?'Búsqueda en línea no disponible. Puedes elegir entre las ciudades disponibles en el móvil.':'No se pudo buscar en línea. Prueba de nuevo con conexión; tus favoritas siguen disponibles.'}finally{clearTimeout(timer)}};
results=[state.active];draw();
})();
